style.css:
@-moz-document domain("calendar.google.com"), domain("tasks.google.com") {
/* Gmail Hacker Green Glass v1.0.25 palette, terminal stack and wallpaper. */
html {
  --hg-font: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace;
  --hg-text: #d9ffe6;
  --hg-secondary: #9ee5b6;
  --hg-muted: #70b68b;
  --hg-icon: #7fffac;
  --hg-focus: #00ff66;
  --hg-action: #00e85c;
  --hg-action-hover: #38ff87;
  --hg-ink: #001b09;
  --hg-sidebar: rgba(3,33,17,.47);
  --hg-panel: rgba(1,22,10,.75);
  --hg-raised: rgba(2,23,11,.97);
  --hg-raised-hover: rgba(4,32,15,.97);
  --hg-tooltip: rgba(1,20,10,.97);
  --hg-toolbar: #021c0e;
  --hg-field: rgba(4,43,20,.95);
  --hg-unread: rgba(3,30,14,.75);
  --hg-selected: rgba(4,54,27,.58);
  --hg-hover: rgba(12,91,39,.56);
  --hg-press: rgba(10,115,43,.61);
  --hg-line: rgba(32,243,107,.18);
  --hg-border: rgba(28,240,102,.36);
  --hg-glow: rgba(37,255,110,.14);
  --hg-right-edge:
    inset -1px 0 0 rgba(0,255,102,.85),
    inset -4px 0 8px -3px rgba(0,255,102,.58),
    inset -10px 0 18px -10px rgba(0,255,102,.35);
  --hg-grid:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px);
  color-scheme: dark !important;
}

/* Calendar Material colors. Event and calendar swatches use their native colors. */
html body {
  --gm3-sys-color-background: #0a0a0a !important;
  --gm3-sys-color-on-background: var(--hg-text) !important;
  --gm3-sys-color-surface: rgba(1,22,10,.46) !important;
  --gm3-sys-color-surface-dim: #061c10 !important;
  --gm3-sys-color-surface-bright: #133522 !important;
  --gm3-sys-color-surface-container-lowest: #02170b !important;
  --gm3-sys-color-surface-container-low: var(--hg-sidebar) !important;
  --gm3-sys-color-surface-container: #082717 !important;
  --gm3-sys-color-surface-container-high: #0a3220 !important;
  --gm3-sys-color-surface-container-highest: #19462b !important;
  --gm3-sys-color-surface-variant: #103422 !important;
  --gm3-sys-color-on-surface: var(--hg-text) !important;
  --gm3-sys-color-on-surface-variant: var(--hg-secondary) !important;
  --gm3-sys-color-outline: #498561 !important;
  --gm3-sys-color-outline-variant: #245035 !important;
  --gm3-sys-color-primary: var(--hg-icon) !important;
  --gm3-sys-color-on-primary: var(--hg-ink) !important;
  --gm3-sys-color-primary-container: #11542d !important;
  --gm3-sys-color-on-primary-container: var(--hg-text) !important;
  --gm3-sys-color-secondary: var(--hg-secondary) !important;
  --gm3-sys-color-on-secondary: var(--hg-ink) !important;
  --gm3-sys-color-secondary-container: #0e4628 !important;
  --gm3-sys-color-on-secondary-container: var(--hg-text) !important;
  --gm3-sys-color-inverse-surface: #09331d !important;
  --gm3-sys-color-inverse-on-surface: var(--hg-text) !important;
  --gm3-sys-color-inverse-primary: var(--hg-icon) !important;
  --gm3-sys-typescale-body-font: var(--hg-font) !important;
  --gm3-sys-typescale-label-font: var(--hg-font) !important;
  --gm3-sys-typescale-title-font: var(--hg-font) !important;
  --gm3-sys-typescale-headline-font: var(--hg-font) !important;
  --og-icon-color: var(--hg-icon) !important;
  --og-logo-color: var(--hg-text) !important;
  background: transparent !important;
  color: var(--hg-text) !important;
  font-family: var(--hg-font) !important;
}

/* The same viewport-aligned 40 px grid and 4 px scan lines as Gmail. */
html,
html body .tNDBE {
  background-color: #0a0a0a !important;
  background-image: var(--hg-grid) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

#gb,
#gb .rSoRzd,
main,
[role="main"],
[role="navigation"],
[role="complementary"],
[role="columnheader"],
[role="rowheader"],
[role="tab"],
[role="menuitem"],
[role="menuitemradio"],
[role="menuitemcheckbox"],
[role="option"],
[role="dialog"],
[role="alertdialog"],
[role="status"],
[role="tooltip"],
button,
input,
textarea,
select,
.r4nke,
.NI2kfb,
.u5sQsb,
.snByac,
.zHQkBf {
  font-family: var(--hg-font) !important;
  font-feature-settings: "zero" 1 !important;
  font-variant-ligatures: none !important;
}

/* Header, navigation, sidebar, bottom strip and Workspace rail. */
html body #gb,
html body header.NkK3Fc,
html body header[role="banner"] {
  background: var(--hg-sidebar) !important;
  color: var(--hg-text) !important;
  box-shadow: inset 0 -1px var(--hg-border) !important;
}

#gb .rSoRzd,
#gb .snByac,
#gb [role="heading"] {
  color: var(--hg-text) !important;
}

#gb img[src*="calendar"],
#gb img[alt="Google Calendar"],
#gb img[alt="Calendar"],
#gb a[aria-label="Google Calendar"] img,
#gb a[aria-label="Google Calendar"] svg,
#gb a[aria-label="Calendar"] img {
  filter: drop-shadow(0 3px 2px rgba(0,255,102,.95))
          drop-shadow(0 4px 8px rgba(0,255,102,.85)) !important;
}

html body #drawer,
html body .QQYuzf,
html body nav[aria-label="Calendars"],
html body [role="navigation"][aria-label="Calendars"] {
  background-color: rgba(4,23,15,.96) !important;
  background-image:
    radial-gradient(ellipse 235% 78% at left top, rgba(20,70,40,.46) 0%, rgba(20,70,40,.12) 62%, rgba(20,70,40,0) 100%),
    var(--hg-grid) !important;
  background-size: 100% 100%, 40px 40px, 40px 40px, 100% 4px !important;
  background-position: left top, 0 0, 0 0, 0 0 !important;
  background-repeat: no-repeat, repeat, repeat, repeat !important;
  background-attachment: scroll, fixed, fixed, fixed !important;
  box-shadow: var(--hg-right-edge) !important;
}

html body .NI2kfb,
html body .MSZkRb .r4nke,
html body .uQ1ixe .snByac {
  color: var(--hg-text) !important;
}

#drawer [role="treeitem"]:hover,
.QQYuzf .NI2kfb:hover,
.QQYuzf .r4nke:hover,
#drawer [role="treeitem"][aria-selected="true"] {
  background-color: var(--hg-hover) !important;
  color: var(--hg-text) !important;
}

html body footer[role="contentinfo"],
html body .tNDBE [role="contentinfo"] {
  background: var(--hg-unread) !important;
  color: var(--hg-secondary) !important;
  box-shadow: inset 0 1px var(--hg-line) !important;
}

html body .Hrn1mc,
html body .Kk7lMc-DWWcKd-OomVLb-haAclf,
html body [role="complementary"],
html body [role="complementary"] [role="tabpanel"],
html body [aria-label="Side panel"] {
  background-color: var(--hg-toolbar) !important;
  color: var(--hg-text) !important;
  border-color: var(--hg-border) !important;
}

[role="complementary"] [role="heading"],
[role="complementary"] header {
  color: var(--hg-text) !important;
  background-color: var(--hg-field) !important;
}

/* Calendar canvas, date headings, grid lines and Today markers. */
html body main,
html body [role="main"]:not(.tNDBE),
html body .SGWAac,
html body .v83gc,
html body .J09ahd {
  background-color: transparent !important;
}

html body .tNDBE,
html body .SGWAac,
html body .CIFHgc,
html body .d3Ig7c,
html body .L1Ysrb,
html body .PhLhOd,
html body .QIadxc,
html body .t8qpF,
html body .zYZlv,
html body .tNDBE [role="gridcell"],
html body .tNDBE [role="columnheader"],
html body .tNDBE [role="rowheader"] {
  border-color: var(--hg-line) !important;
}

html body .tNDBE [role="columnheader"],
html body .tNDBE [role="rowheader"] {
  color: var(--hg-secondary) !important;
}

html body .tNDBE [role="columnheader"] {
  background-color: var(--hg-panel) !important;
  color: var(--hg-secondary) !important;
}

html body .ef2wWc,
html body .SU7tYb.F262Ye,
html body .yEkOpe.F262Ye,
html body .W0m3G.i8dSE .r4nke {
  background-color: var(--hg-selected) !important;
}

html body .YK7obe,
html body .w48V4c,
html body .yzYBvd,
html body .r4nke {
  color: var(--hg-text) !important;
}

html body .w48V4c.F262Ye,
html body .yzYBvd.F262Ye,
html body .TUH0Sd .r4nke,
html body .OmwDud.F262Ye .O3EOA,
html body .tNDBE [aria-current="date"] {
  background-color: var(--hg-action) !important;
  color: var(--hg-ink) !important;
  box-shadow: 0 0 11px var(--hg-glow) !important;
}

html body .tNDBE [role="gridcell"]:focus-visible {
  outline: 2px solid var(--hg-focus) !important;
  outline-offset: -2px !important;
}

html body .tNDBE .wy3aMe,
html body .KSxb4d,
html body .OmwDud,
html body .taTyDe {
  color: var(--hg-secondary) !important;
}

html body .tNDBE [data-eventid],
html body .dtaVuc,
html body .g3dbUc {
  font-family: var(--hg-font) !important;
}

html body .tNDBE [data-eventid]:hover,
html body .g3dbUc:hover,
html body .dtaVuc:hover {
  box-shadow: inset 0 0 0 1px rgba(0,255,102,.75), 0 0 9px var(--hg-glow) !important;
}

html body .tNDBE [data-eventid]:focus-visible,
html body .g3dbUc:focus-visible {
  outline: 2px solid var(--hg-focus) !important;
  outline-offset: -2px !important;
}

/* Today, view switcher, icon buttons, Create and event actions. */
html body #gb .GXlaye,
html body #gb [aria-label="Calendar"][aria-pressed],
html body #gb [aria-label="Tasks"][aria-pressed],
html body #gb .Rj2Mlf:not(:disabled),
html body #gb [aria-label="Today"],
html body [role="dialog"] button[aria-haspopup]:not([style*="background"]),
html body [role="dialog"] [role="combobox"]:not([style*="background"]) {
  background-color: var(--hg-field) !important;
  border-color: var(--hg-border) !important;
  color: var(--hg-text) !important;
}

html body #gb .GXlaye:hover,
html body #gb .Rj2Mlf:not(:disabled):hover,
#gb button:not([disabled]):hover,
#gb [role="button"]:not([aria-disabled="true"]):hover,
[role="complementary"] button:not([disabled]):hover,
.cOoA8d button:not([disabled]):hover {
  background-color: var(--hg-hover) !important;
}

#gb button[aria-pressed="true"],
#gb [role="button"][aria-pressed="true"],
#gb button[aria-expanded="true"],
#gb [role="button"][aria-expanded="true"],
[role="complementary"] button[aria-pressed="true"] {
  background-color: var(--hg-selected) !important;
}

#gb button,
#gb [role="button"],
[role="complementary"] button,
[role="dialog"] button,
[role="alertdialog"] button {
  color: var(--hg-icon) !important;
}

/* Clear the view switcher wrapper and its control so the header grid shows. */
html body #gb .Cd9hpd,
html body #gb .Cd9hpd.Rj2Mlf,
html body #gb .Cd9hpd .Rj2Mlf,
html body #gb .Cd9hpd button,
html body #gb .Cd9hpd [role="button"],
html body #gb button[aria-haspopup="listbox"],
html body #gb [role="button"][aria-haspopup="listbox"],
html body #gb [aria-label="Month"][aria-haspopup] {
  background: transparent !important;
  border-color: var(--hg-border) !important;
  color: var(--hg-text) !important;
}

/* Keep the hover and expanded tint on the pill, including when it is the wrapper. */
html body #gb button.Cd9hpd:not(:disabled):hover,
html body #gb .Cd9hpd[role="button"]:not([aria-disabled="true"]):hover,
html body #gb .Cd9hpd button:not(:disabled):hover,
html body #gb .Cd9hpd [role="button"]:not([aria-disabled="true"]):hover,
html body #gb button[aria-haspopup="listbox"]:not(:disabled):hover,
html body #gb [role="button"][aria-haspopup="listbox"]:not([aria-disabled="true"]):hover,
html body #gb .Cd9hpd button[aria-expanded="true"],
html body #gb .Cd9hpd [role="button"][aria-expanded="true"],
html body #gb button[aria-haspopup="listbox"][aria-expanded="true"],
html body #gb [role="button"][aria-haspopup="listbox"][aria-expanded="true"] {
  background-color: var(--hg-hover) !important;
}

html body .SaBhMc,
html body .QQYuzf .buGMKc,
html body .Y5sE8d:not(:disabled),
html body #drawer button[aria-label="Create"],
html body [role="dialog"] button[type="submit"]:not(:disabled),
html body [role="dialog"] button[aria-label="Save"]:not(:disabled),
html body [role="dialog"] [role="button"][aria-label="Save"]:not([aria-disabled="true"]),
html body [data-viewfamily="EVENT_EDIT"] button[aria-label="Save"]:not(:disabled),
html body[data-viewfamily="EVENT_EDIT"] button[aria-label="Save"]:not(:disabled) {
  background: var(--hg-action) !important;
  border-color: var(--hg-action) !important;
  color: var(--hg-ink) !important;
}

.SaBhMc .u5sQsb,
.QQYuzf .buGMKc .mr0WL,
.Y5sE8d:not(:disabled) .snByac,
.SaBhMc .snByac,
[role="dialog"] button[type="submit"]:not(:disabled) .snByac,
[role="dialog"] button[aria-label="Save"]:not(:disabled) .snByac,
body[data-viewfamily="EVENT_EDIT"] button[aria-label="Save"]:not(:disabled) .snByac {
  color: var(--hg-ink) !important;
}

html body .SaBhMc:hover,
html body .QQYuzf .buGMKc:hover,
html body .Y5sE8d:not(:disabled):hover,
html body #drawer button[aria-label="Create"]:hover,
html body [role="dialog"] button[type="submit"]:not(:disabled):hover,
html body [role="dialog"] button[aria-label="Save"]:not(:disabled):hover,
html body [role="dialog"] [role="button"][aria-label="Save"]:not([aria-disabled="true"]):hover,
html body [data-viewfamily="EVENT_EDIT"] button[aria-label="Save"]:not(:disabled):hover,
html body[data-viewfamily="EVENT_EDIT"] button[aria-label="Save"]:not(:disabled):hover {
  background: var(--hg-action-hover) !important;
  box-shadow: 0 0 14px var(--hg-glow) !important;
}

button:focus-visible,
a:focus-visible,
[role="button"]:focus-visible,
[role="tab"]:focus-visible,
[role="checkbox"]:focus-visible,
[role="menuitem"]:focus-visible,
[role="option"]:focus-visible,
[contenteditable="true"]:focus-visible {
  outline: 2px solid var(--hg-focus) !important;
  outline-offset: -2px !important;
}

/* Search, filters, editor fields and suggestions. */
html body form[role="search"],
html body [role="search"],
html body .ULpymb,
html body .QQYuzf [role="combobox"],
html body [role="dialog"] input:not([type="checkbox"]):not([type="radio"]):not([type="color"]),
html body [role="dialog"] textarea,
html body [role="dialog"] select,
html body[data-viewfamily="EVENT_EDIT"] input:not([type="checkbox"]):not([type="radio"]):not([type="color"]),
html body [data-viewfamily="EVENT_EDIT"] input:not([type="checkbox"]):not([type="radio"]):not([type="color"]),
html body[data-viewfamily="EVENT_EDIT"] textarea,
html body[data-viewfamily="EVENT_EDIT"] select,
html body[data-viewfamily="SETTINGS"] input[type="text"],
html body[data-viewfamily="SETTINGS"] select {
  background-color: var(--hg-field) !important;
  color: var(--hg-text) !important;
  border-color: var(--hg-border) !important;
}

form[role="search"],
[role="search"],
.ULpymb {
  box-shadow: inset 0 0 0 1px var(--hg-border) !important;
}

html body [role="search"] input,
html body .ULpymb input {
  background: transparent !important;
  color: var(--hg-text) !important;
}

input,
textarea,
[contenteditable="true"] {
  caret-color: var(--hg-focus) !important;
}

input::placeholder,
textarea::placeholder {
  color: var(--hg-secondary) !important;
  opacity: 1 !important;
}

input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--hg-action) !important;
}

input:focus-visible,
textarea:focus-visible,
select:focus-visible,
[role="combobox"]:focus-visible {
  outline: 2px solid var(--hg-focus) !important;
  outline-offset: -2px !important;
}

/* Popovers, event details, menus, notices and tooltips. */
html body dialog,
html body [role="dialog"],
html body [role="alertdialog"],
html body [role="menu"],
html body [role="listbox"],
html body .JPdR6b,
html body .ncFHed,
html body [data-chips-dialog],
html body .jBmls,
html body .JtukPc {
  background-color: var(--hg-raised) !important;
  border-color: var(--hg-border) !important;
  color: var(--hg-text) !important;
  box-shadow: inset 0 0 0 1px var(--hg-border), 0 14px 38px rgba(0,0,0,.57), 0 0 18px var(--hg-glow) !important;
}

html body .RDlrG {
  box-shadow: 0 16px 40px rgba(0,0,0,.55), 0 0 16px var(--hg-glow) !important;
}

html body .NAFvr,
html body [role="dialog"] [role="tablist"],
html body [role="dialog"] footer {
  background-color: var(--hg-toolbar) !important;
  color: var(--hg-text) !important;
  border-color: var(--hg-line) !important;
}

[role="menuitem"],
[role="menuitemradio"],
[role="menuitemcheckbox"],
[role="option"],
[role="dialog"] [role="heading"],
[role="alertdialog"] [role="heading"],
.agOyMd .JAPzS,
.agOyMd .DN1TJ,
.NAFvr .YTCBlf {
  color: var(--hg-text) !important;
}

[role="menuitem"]:not([aria-disabled="true"]):not([style*="background"]):hover,
[role="menuitemradio"]:not([aria-disabled="true"]):not([style*="background"]):hover,
[role="menuitemcheckbox"]:not([aria-disabled="true"]):not([style*="background"]):hover,
[role="option"]:not([aria-disabled="true"]):not([style*="background"]):hover,
[role="option"][aria-selected="true"]:not([style*="background"]),
[role="menuitemradio"][aria-checked="true"]:not([style*="background"]),
[role="menuitemcheckbox"][aria-checked="true"]:not([style*="background"]),
.JPdR6b .z80M1.FwR7Pc,
.VKy0Ic[aria-selected="true"],
.oKubKe[aria-selected="true"] {
  background-color: var(--hg-hover) !important;
  color: var(--hg-text) !important;
}

html body [role="tooltip"] {
  background-color: var(--hg-tooltip) !important;
  color: var(--hg-text) !important;
  box-shadow: inset 0 0 0 1px var(--hg-line) !important;
}

html body .tNDBE [role="status"],
html body [role="main"] [role="status"],
html body [role="alert"] {
  background-color: var(--hg-panel) !important;
  color: var(--hg-text) !important;
  border-color: var(--hg-line) !important;
}

html body .tNDBE [role="status"] a,
html body [role="alert"] a,
html body [role="dialog"] a[href^="https://calendar.google.com/"] {
  color: var(--hg-icon) !important;
}

/* Full editor and settings. Match the navigation, tab and table treatments. */
html body[data-viewfamily="EVENT_EDIT"] [role="main"],
html body[data-viewfamily="SETTINGS"] .MDfQ7,
html body[data-viewfamily="SETTINGS"] .Lzfnue,
html body[data-viewfamily="SETTINGS"] [role="main"],
html body[data-viewfamily="SETTINGS"] main,
html body [role="main"][aria-label="Settings"] {
  background-color: var(--hg-panel) !important;
  color: var(--hg-text) !important;
}

html body[data-viewfamily="SETTINGS"] .xWId8e,
html body[data-viewfamily="SETTINGS"] [role="navigation"],
html body[data-viewfamily="SETTINGS"] [role="tablist"],
html body [aria-label="Settings"] [role="tablist"] {
  background-color: var(--hg-sidebar) !important;
  box-shadow: inset 0 -1px var(--hg-line) !important;
}

html body[data-viewfamily="SETTINGS"] .M1ZIGd,
html body[data-viewfamily="SETTINGS"] th,
html body[data-viewfamily="SETTINGS"] [role="columnheader"] {
  background-color: var(--hg-toolbar) !important;
  color: var(--hg-text) !important;
  border-color: var(--hg-line) !important;
}

[role="tab"]:not([aria-disabled="true"]):hover,
body[data-viewfamily="SETTINGS"] [role="navigation"] a:hover {
  background-color: var(--hg-hover) !important;
}

[role="tab"][aria-selected="true"],
body[data-viewfamily="SETTINGS"] .cAYGed.KKjvXb .Ioup7e,
body[data-viewfamily="SETTINGS"] .LOewLb.KKjvXb,
body[data-viewfamily="SETTINGS"] [aria-current="page"] {
  background-color: var(--hg-selected) !important;
  color: var(--hg-text) !important;
  box-shadow: inset 0 -2px var(--hg-focus) !important;
}

html body[data-viewfamily="SETTINGS"] .ETUnje,
html body[data-viewfamily="SETTINGS"] .jxUZDd {
  border-color: var(--hg-line) !important;
}

html body[data-viewfamily="SETTINGS"] .ETUnje:hover,
html body[data-viewfamily="SETTINGS"] .jxUZDd:hover {
  background-color: var(--hg-hover) !important;
}

/* Tasks runs in its own document inside Calendar and on tasks.google.com. */
html body iframe[src^="https://tasks.google.com/"] {
  background-color: transparent !important;
}

html body#TasksApp {
  --boq-chrometransition-background: #0a0a0a !important;
  --tasks-font-family: var(--hg-font) !important;
  --tasks-body-background: #0a0a0a !important;
  --tasks-background: #0a0a0a !important;
  --tasks-list-background: var(--hg-panel) !important;
  --tasks-editing-task-background: var(--hg-field) !important;
  --tasks-surface-transparent: transparent !important;
  --tasks-surface: var(--hg-panel) !important;
  --tasks-surface-container: #082717 !important;
  --tasks-surface-container-low: var(--hg-sidebar) !important;
  --tasks-surface-container-high: var(--hg-field) !important;
  --tasks-primary: var(--hg-icon) !important;
